mapper.select:
select SEQ_NO as seqNo, BATCH_EXE_SEQ_NO as batchExeSeqNo, TASK_ID as taskId, BOOKSET_ID as booksetId, DATE_FORMAT(HAPPEN_DATE,'%Y-%m-%d')as happenDate, DATE_FORMAT(BOOKSET_DATE,'%Y-%m-%d') as booksetDate, DATE_FORMAT(BOOK_DATE,'%Y-%m-%d') as bookDate, FINPROD_ID as finprodId, FINPROD_TYPE as finprodType, MARKET_CODE as marketCode, INV_AIM as invAim, VALUE_SOURCE as valueSource, DATE_FORMAT(THE_VALUE_DATE,'%Y-%m-%d') as theValueDate, DATE_FORMAT(ACT_VALUE_DATE,'%Y-%m-%d') as actValueDate, ACT_MARKET_PRICE as actMarketPrice from BOK_BATCH_MARKETWARNING_INFO where 1=1
AND BATCH_EXE_SEQ_NO = #{batchExedetailSeqNo}
AND TASK_ID = #{taskId}
